#!/usr/bin/env python3
"""Payroll summary: python3 payroll.py INPUT_DIR OUTPUT_FILE (see /app/docs)."""
import csv
import gzip
import io
import json
import os
import re
import sys
from datetime import date, datetime, timedelta, timezone
from decimal import Decimal
from fractions import Fraction
from zoneinfo import ZoneInfo

UTC = timezone.utc
EPOCH = datetime(1970, 1, 1, tzinfo=UTC)


# ---------------------------------------------------------------- helpers
def read_text(path):
    with open(path, "rb") as f:
        b = f.read()
    if b[:2] == b"\x1f\x8b":
        b = gzip.decompress(b)
    t = b.decode("utf-8-sig")
    return t


def read_lines(path):
    # splitlines would also split on odd unicode separators; use \n only
    t = read_text(path)
    out = []
    for ln in t.split("\n"):
        if ln.endswith("\r"):
            ln = ln[:-1]
        if ln.strip() == "":
            continue
        out.append(ln)
    return out


def list_files(d):
    res = []
    if not os.path.isdir(d):
        return res
    for root, _, files in os.walk(d):
        for fn in files:
            res.append(os.path.join(root, fn))
    return sorted(res)


def to_epoch(dt):
    """aware datetime -> integer seconds"""
    delta = dt - EPOCH
    return delta.days * 86400 + delta.seconds


def local_to_utc(naive, tz, dst=None):
    """naive local datetime -> epoch seconds. dst: None (first occurrence),
    True/False to choose among a repeated local time."""
    d0 = naive.replace(tzinfo=tz, fold=0)
    d1 = naive.replace(tzinfo=tz, fold=1)
    o0, o1 = d0.utcoffset(), d1.utcoffset()
    if o0 > o1:  # ambiguous (clocks went back)
        if dst is None or dst:
            pick = d0
        else:
            pick = d1
    else:
        pick = d0
    return to_epoch(pick.astimezone(UTC))


def parse_iso_offset(s):
    s = s.strip()
    if s.endswith("Z") or s.endswith("z"):
        s = s[:-1] + "+00:00"
    dt = datetime.fromisoformat(s)
    if dt.tzinfo is None:
        raise ValueError("no offset: " + s)
    return to_epoch(dt)


def csv_rows(lines, delimiter, key_cols):
    """Yield dict rows; header rows (re)appearing anywhere switch the header."""
    header = None
    keyset = set(key_cols)
    for row in csv.reader(lines, delimiter=delimiter):
        if not row or all(c.strip() == "" for c in row):
            continue
        cells = [c.strip() for c in row]
        if keyset.issubset(set(cells)):
            header = cells
            continue
        if header is None:
            continue
        yield dict(zip(header, row))


# ---------------------------------------------------------------- readers
# Each reader yields (punch_id, employee, direction('IN'/'OUT'), epoch_seconds)

def read_abbr_csv(path, tz):
    for r in csv_rows(read_lines(path), ",", ["Badge", "Punch", "Date", "Time"]):
        emp = r["Badge"].strip()
        d = r["Punch"].strip().upper()
        m, dd, yy = r["Date"].strip().split("/")
        t = r["Time"].strip()
        mt = re.fullmatch(r"(\d{1,2}):(\d\d):(\d\d)\s*([AaPp][Mm])?", t)
        h, mi, s = int(mt.group(1)), int(mt.group(2)), int(mt.group(3))
        ap = mt.group(4)
        if ap:
            ap = ap.upper()
            h = h % 12
            if ap == "PM":
                h += 12
        naive = datetime(int(yy), int(m), int(dd), h, mi, s)
        z = (r.get("Zone") or "").strip().upper()
        dst = None
        if z.endswith("DT"):
            dst = True
        elif z.endswith("ST"):
            dst = False
        yield r["Record"].strip(), emp, d, local_to_utc(naive, tz, dst)


def read_epoch_jsonl(path, tz):
    schema = 1
    for ln in read_lines(path):
        o = json.loads(ln)
        if not isinstance(o, dict):
            continue
        if "schema" in o and "id" not in o and "punch_id" not in o:
            schema = int(o["schema"])
            continue
        if o.get("heartbeat") is True:
            continue
        if schema == 2:
            if "punch_id" not in o:
                continue
            ts = int(o["epoch_ms"]) // 1000
            yield str(o["punch_id"]), str(o["employee"]).strip(), str(o["direction"]).strip().upper(), ts
        else:
            if "id" not in o:
                continue
            if "ts_ms" in o:
                ts = int(o["ts_ms"]) // 1000
            else:
                ts = int(o["ts"])
            yield str(o["id"]), str(o["emp"]).strip(), str(o["dir"]).strip().upper(), ts


def read_offset_csv(path, tz):
    for r in csv_rows(read_lines(path), ";", ["punch_id", "employee", "event", "timestamp"]):
        ev = r["event"].strip().lower()
        d = "IN" if ev == "clock_in" else "OUT"
        yield r["punch_id"].strip(), r["employee"].strip(), d, parse_iso_offset(r["timestamp"])


def std_offset_seconds(tz):
    dt = datetime(2026, 1, 15, tzinfo=tz)
    off = dt.utcoffset() - (dt.dst() or timedelta(0))
    return int(off.total_seconds())


def read_legacy(path, tz):
    default = std_offset_seconds(tz)
    cur = default
    for ln in read_lines(path):
        c = ln[0]
        if c == "H":
            m = re.fullmatch(r"([+-])(\d\d)(\d\d)", ln[13:18].strip()) if len(ln) >= 18 else None
            if m:
                cur = (1 if m.group(1) == "+" else -1) * (int(m.group(2)) * 3600 + int(m.group(3)) * 60)
            else:
                cur = default
        elif c == "D":
            pid = ln[1:9]
            badge = ln[9:15].strip()
            d = "IN" if ln[15] == "I" else "OUT"
            dt = datetime.strptime(ln[16:30], "%Y%m%d%H%M%S").replace(tzinfo=UTC)
            ts = to_epoch(dt) - cur
            yield pid, "E" + badge, d, ts


def read_de_tsv(path, tz):
    for r in csv_rows(read_lines(path), "\t", ["Ausweis", "Buchung", "Datum", "Uhrzeit"]):
        d = "IN" if r["Buchung"].strip().upper() == "K" else "OUT"
        dd, mm, yy = r["Datum"].strip().split(".")
        t = r["Uhrzeit"].strip().split(":")
        naive = datetime(int(yy), int(mm), int(dd), int(t[0]), int(t[1]), int(t[2]) if len(t) > 2 else 0)
        z = (r.get("Zeitzone") or "").strip().upper()
        dst = None
        if z == "MESZ":
            dst = True
        elif z == "MEZ":
            dst = False
        yield r["Nr"].strip(), r["Ausweis"].strip(), d, local_to_utc(naive, tz, dst)


def read_local_csv(path, tz):
    for r in csv_rows(read_lines(path), ",", ["employee_id", "direction", "local_time", "punch_ref"]):
        naive = datetime.strptime(r["local_time"].strip(), "%Y-%m-%d %H:%M:%S")
        yield (r["punch_ref"].strip(), r["employee_id"].strip(), r["direction"].strip().upper(),
               local_to_utc(naive, tz, None))


def read_local_jsonl(path, tz):
    for ln in read_lines(path):
        o = json.loads(ln)
        if not isinstance(o, dict) or not isinstance(o.get("punch"), dict):
            continue
        p = o["punch"]
        naive = datetime.strptime(p["at"].strip(), "%Y-%m-%d %H:%M:%S")
        pid = p["id"]
        pid = str(pid)
        yield pid, str(p["badge"]).strip(), str(p["type"]).strip().upper(), local_to_utc(naive, tz, None)


READERS = {
    "abbr-csv": read_abbr_csv,
    "epoch-jsonl": read_epoch_jsonl,
    "offset-csv": read_offset_csv,
    "legacy-fixed": read_legacy,
    "de-tsv": read_de_tsv,
    "local-csv": read_local_csv,
    "local-jsonl": read_local_jsonl,
}


# ---------------------------------------------------------------- main logic
def round_punch(ts, tz):
    off = int(datetime.fromtimestamp(ts, UTC).astimezone(tz).utcoffset().total_seconds())
    local = ts + off
    r = local % 360
    if r >= 180:
        return ts + (360 - r)
    return ts - r


def main(indir, outfile):
    with open(os.path.join(indir, "period.json")) as f:
        period = json.load(f)
    pstart = date.fromisoformat(period["start"])
    pend = date.fromisoformat(period["end"])
    cutoff = parse_iso_offset(period["corrections_cutoff"])

    sites = {}
    with open(os.path.join(indir, "sites.csv"), newline="", encoding="utf-8-sig") as f:
        for r in csv.DictReader(f):
            sites[r["site"].strip()] = (ZoneInfo(r["timezone"].strip()), r["format"].strip())

    employees = {}
    with open(os.path.join(indir, "employees.csv"), newline="", encoding="utf-8-sig") as f:
        for r in csv.DictReader(f):
            employees[r["employee_id"].strip()] = r["home_site"].strip()

    rates = {}
    with open(os.path.join(indir, "rates.csv"), newline="", encoding="utf-8-sig") as f:
        for r in csv.DictReader(f):
            rates.setdefault(r["employee_id"].strip(), []).append(
                (date.fromisoformat(r["effective_from"].strip()), Fraction(Decimal(r["hourly_rate"].strip()))))
    for v in rates.values():
        v.sort(key=lambda x: x[0])

    # 1. collect punches: (site, pid) -> [emp, dir, ts]
    punches = {}
    ever = set()
    for site, (tz, fmt) in sites.items():
        reader = READERS[fmt]
        for path in list_files(os.path.join(indir, "exports", site)):
            for pid, emp, d, ts in reader(path, tz):
                key = (site, pid)
                if key in punches:
                    continue
                punches[key] = [emp, d, ts]
                ever.add(key)

    # 2. corrections
    corr = []
    for path in list_files(os.path.join(indir, "corrections")):
        for r in csv_rows(read_lines(path), ",", ["correction_id", "issued_at", "action"]):
            corr.append(r)
    items = []
    for r in corr:
        issued = parse_iso_offset(r["issued_at"])
        if issued > cutoff:
            continue
        items.append((issued, r["correction_id"].strip(), r))
    items.sort(key=lambda x: (x[0], x[1]))
    applied = 0
    for _, _, r in items:
        act = r["action"].strip().lower()
        key = (r["site"].strip(), r["punch_id"].strip())
        if act == "void":
            if key in punches:
                del punches[key]
                applied += 1
        elif act == "set":
            if key in punches:
                punches[key][2] = parse_iso_offset(r["time"])
                applied += 1
        elif act == "add":
            if key not in ever and key[0] in sites:
                punches[key] = [r["employee"].strip(), r["type"].strip().upper(), parse_iso_offset(r["time"])]
                ever.add(key)
                applied += 1

    byemp = {}
    for (site, pid), (emp, d, ts) in punches.items():
        if emp not in employees:
            continue
        byemp.setdefault(emp, []).append((ts, 0 if d == "OUT" else 1, site, pid, d))

    zones = {s: v[0] for s, v in sites.items()}

    def workday(ts, emp):
        tz = zones[employees[emp]]
        return datetime.fromtimestamp(ts, UTC).astimezone(tz).date()

    res = {e: {"shifts": 0, "paid": 0, "ot": 0, "night": 0, "pay": Fraction(0)} for e in employees}
    exc = {"open_shifts": 0, "orphan_outs": 0, "duplicates_dropped": 0}

    def in_period(wd):
        return pstart <= wd <= pend

    for emp, lst in byemp.items():
        lst.sort()
        # 3. duplicates
        kept = []
        last = None
        for ts, _, site, pid, d in lst:
            if last is not None and last[4] == d and ts - last[0] <= 300:
                rts = round_punch(ts, zones[site])
                if in_period(workday(rts, emp)):
                    exc["duplicates_dropped"] += 1
                continue
            last = (ts, 0, site, pid, d)
            kept.append((ts, site, pid, d))
        # 4. round
        rk = [(round_punch(ts, zones[site]), ts, site, pid, d) for ts, site, pid, d in kept]
        # 5. pair
        shifts = []
        i = 0
        n = len(rk)
        while i < n:
            p = rk[i]
            if p[4] == "IN":
                if i + 1 < n and rk[i + 1][4] == "OUT" and rk[i + 1][0] - p[0] <= 16 * 3600:
                    shifts.append((p, rk[i + 1]))
                    i += 2
                    continue
                if in_period(workday(p[0], emp)):
                    exc["open_shifts"] += 1
                i += 1
            else:
                if in_period(workday(p[0], emp)):
                    exc["orphan_outs"] += 1
                i += 1
        # 6/7. shifts of the period
        rows = []
        for pin, pout in shifts:
            wd = workday(pin[0], emp)
            if not in_period(wd):
                continue
            worked = max(0, (pout[0] - pin[0]) // 60)
            paid = worked - 30 if worked > 360 else worked
            tz = zones[pin[2]]
            night = 0
            t = pin[0]
            while t < pout[0]:
                loc = datetime.fromtimestamp(t, UTC).astimezone(tz)
                mod = loc.hour * 60 + loc.minute
                if mod >= 1320 or mod < 360:
                    night += 1
                t += 60
            night = min(night, paid)
            rows.append([pin[0], wd, paid, night, 0])
        rows.sort(key=lambda x: x[0])
        # 8. overtime
        daily_used = {}
        for row in rows:
            used = daily_used.get(row[1], 0)
            reg = max(0, min(row[2], 480 - used))
            row.append(row[2] - reg)  # daily ot -> index 5
            daily_used[row[1]] = used + row[2]
        week_used = {}
        for row in rows:
            wk = row[1] - timedelta(days=row[1].weekday())
            nondaily = row[2] - row[5]
            used = week_used.get(wk, 0)
            wreg = max(0, min(nondaily, 2400 - used))
            wot = nondaily - wreg
            week_used[wk] = used + nondaily
            row[4] = row[5] + wot
        r = res[emp]
        for ts, wd, paid, night, ot, _ in rows:
            rate = Fraction(0)
            for eff, val in rates.get(emp, []):
                if eff <= wd:
                    rate = val
            regular = paid - ot
            r["shifts"] += 1
            r["paid"] += paid
            r["ot"] += ot
            r["night"] += night
            r["pay"] += rate * (Fraction(regular) + Fraction(3, 2) * ot) / 60 + rate * Fraction(15, 100) * night / 60

    out_emps = {}
    tot = {"shifts": 0, "paid_minutes": 0, "overtime_minutes": 0, "night_minutes": 0}
    totgross = 0
    for e in sorted(employees):
        r = res[e]
        cents = int((r["pay"] * 100 + Fraction(1, 2)) // 1)
        out_emps[e] = {
            "shifts": r["shifts"], "paid_minutes": r["paid"], "overtime_minutes": r["ot"],
            "night_minutes": r["night"], "gross": "%d.%02d" % divmod(cents, 100),
        }
        tot["shifts"] += r["shifts"]
        tot["paid_minutes"] += r["paid"]
        tot["overtime_minutes"] += r["ot"]
        tot["night_minutes"] += r["night"]
        totgross += cents
    tot["gross"] = "%d.%02d" % divmod(totgross, 100)
    exc["corrections_applied"] = applied
    out = {"period": {"start": period["start"], "end": period["end"]},
           "employees": out_emps, "exceptions": exc, "totals": tot}
    d = os.path.dirname(os.path.abspath(outfile))
    os.makedirs(d, exist_ok=True)
    with open(outfile, "w") as f:
        json.dump(out, f, indent=1)


if __name__ == "__main__":
    if len(sys.argv) != 3:
        sys.exit("usage: payroll.py INPUT_DIR OUTPUT_FILE")
    main(sys.argv[1], sys.argv[2])
